'use client';

import type {
  CSSProperties,
  HTMLAttributes,
  ReactNode
} from 'react';


type MergedShapeProps = HTMLAttributes<HTMLDivElement> & {
  fill?: string;
  children?: ReactNode;
  style?: CSSProperties;
};



function BentoLabel({
  number,
  title,
  line,
  className = '',
}: {
  number?: ReactNode;
  title: ReactNode;
  line?: ReactNode;
  className?: string;
}) {

  return (
    <div
      className={`
        absolute
        flex
        h-full
        w-full
        flex-col
        justify-start
        gap-2
        pt-2
        pr-2
        pb-2
        pl-4
        sm:pt-5
        sm:pr-5
        sm:pb-5
        ${className}
      `}
    >

      {number && (
        <span
          className="
            font-bitcount
            text-[10px]
            uppercase
            tracking-[0.45em]
            text-white/40
          "
        >
          {number}
        </span>
      )}


      <div>

        <h3
          className="
            bento-title
            max-w-[12ch]
            text-[clamp(1.8rem,3vw,3rem)]
            leading-[0.88]
            tracking-[-0.05em]
            text-white
          "
        >
          {title}
        </h3>


        {line && (
          <p
            className="
              bento-line
              mt-4
              max-w-[20ch]
              font-bitcount
              text-[10px]
              uppercase
              leading-[1.8]
              tracking-[0.25em]
              text-white/50
            "
          >
            {line}
          </p>
        )}

      </div>

    </div>
  );
}

function IdentityLabel() {
  return (
    <div className="absolute inset-0 flex flex-col px-3 pt-4 pb-6 sm:px-4 sm:pt-5">
      <span className="mt-[5%] font-bitcount shrink-0 text-[10px] uppercase tracking-[0.55em] text-white/40">
        00 / IDENTITY
      </span>

      <div className="mt-[60%] flex flex-col">
        <h3 className="bento-title m-0 p-0 text-left text-[clamp(2.7rem,4vw,3.8rem)] leading-[0.88] tracking-[-0.04em] text-white">
          SATHWIK G
        </h3>
        <div className="mt-3 h-px w-[min(100%,11ch)] bg-white/45" aria-hidden />
        <p className="bento-line mt-4 text-left text-[clamp(0.7rem,1.1vw,0.85rem)] uppercase leading-[1.7] tracking-[0.22em] text-white/55">
          DIGITAL CRAFT.
          <br />
          AI SYSTEMS.
          <br />
          HUMAN EXPERIENCE.
        </p>
      </div>
    </div>
  );
}



